/* Original vector teaching models. Values are illustrative, not field observations. */
(function(global){
const C={green:'#b8d99b',gold:'#e6c37e',blue:'#91cad8',coral:'#e2a68c',muted:'#89aa97',line:'#719480'};
const text=(x,y,s,size=15,color=C.green,anchor='middle')=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" text-anchor="${anchor}" font-family="Segoe UI,Microsoft YaHei,sans-serif">${s}</text>`;
const path=(d,color=C.green,width=2,extra='')=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" ${extra}/>`;
function frame(body,id){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 440" role="img" aria-label="${id}"><defs><radialGradient id="bg"><stop stop-color="#28533f"/><stop offset="1" stop-color="#173b31"/></radialGradient><linearGradient id="water" x2="0" y2="1"><stop stop-color="#8dbba9" stop-opacity=".28"/><stop offset="1" stop-color="#8dbba9" stop-opacity=".03"/></linearGradient><linearGradient id="leaf" x2="1" y2="1"><stop stop-color="#d4df9d"/><stop offset="1" stop-color="#6eab7c"/></linearGradient><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="${C.muted}"/></marker></defs><rect width="720" height="440" fill="url(#bg)"/>${body}</svg>`}
function plant(cx,base,scale=1){return `<g transform="translate(${cx} ${base}) scale(${scale})">${path('M0 0C-10-52 10-89 3-150',C.green,4)}<path d="M1-64C-52-56-77-92-66-113C-31-118-7-93 1-64Z" fill="url(#leaf)"/><path d="M2-97C49-80 74-112 67-138C32-144 8-126 2-97Z" fill="url(#leaf)"/><path d="M4-141C-25-141-37-165-28-181C-5-179 6-162 4-141Z" fill="url(#leaf)"/>${path('M-60-107L0-65M7-101L61-131','#d6e5b1',1)}${path('M0 0C-12 24 13 48 0 92M-3 15C-21 29-36 30-48 55M0 35C18 46 32 47 47 74M0 55L-22 82M0 70L19 94','#d6cfac',2)}${path('M-35 40L-44 33M-28 35L-34 28M34 59L43 52M-12 70L-24 65M12 84L26 79','#9aab88',1)}</g>`}
function flow(d,color=C.gold,delay=0){return `<circle r="4" fill="${color}" class="moving"><animateMotion dur="4s" begin="-${delay}s" repeatCount="indefinite" path="${d}"/></circle>`}
function uptake(p={},step=3,cover=false){let s=plant(360,247,1.05);s+=`<ellipse cx="360" cy="253" rx="190" ry="40" fill="#b9c39a" opacity=".08"/>${path('M104 253Q360 223 616 253','#8ea984',1)}<path d="M155 255Q360 227 565 255L565 371Q360 405 155 371Z" fill="url(#water)" stroke="#88a78b" stroke-opacity=".2"/>`;for(let i=0;i<18;i++){const x=185+(i*83)%350,y=280+(i*37)%88;s+=`<circle cx="${x}" cy="${y}" r="${2+i%3}" fill="${[C.gold,C.blue,C.green][i%3]}" opacity=".55"/>`}
if(step>=1){s+=path('M200 310Q270 260 347 281',C.gold,1,'stroke-dasharray="4 6"');s+=path('M520 326Q445 286 376 295',C.blue,1,'stroke-dasharray="4 6"');s+=flow('M200 310Q270 260 347 281',C.gold)+flow('M520 326Q445 286 376 295',C.blue,2)}if(step>=2){s+=flow('M347 281L359 279L360 249',C.gold,1);s+=`<circle cx="359" cy="278" r="17" fill="none" stroke="${C.gold}" opacity=".5" stroke-dasharray="3 4"/>`}
if(step>=3){s+=flow('M360 280C348 213 367 174 362 101',C.blue,1)+flow('M360 280C348 213 367 174 362 101',C.gold,3)}
if(!cover){s+=text(168,321,'土壤溶液',13,C.muted);s+=text(544,325,'NO₃⁻ · NH₄⁺ · K⁺',14,C.gold);if(step>=1)s+=text(192,278,'迁移到根表',13,C.gold);if(step>=2)s+=text(423,287,'跨膜吸收',13,C.green);if(step>=3)s+=text(467,135,'木质部运输 ↑',13,C.blue);s+=text(360,415,'路径示意 · 不同离子的运输机制有所不同',10,C.muted)}return frame(s,'根系吸收养分路径')}
function minimum(p={},step=1,cover=false){let n=p.n??80,ph=p.p??35,k=p.k??70;let vals=[n,ph,k,90,85,95],names=['N','P','K','Ca','Mg','S'],min=Math.min(...vals),lim=names[vals.indexOf(min)];let s='';for(let i=0;i<6;i++){let x=210+i*48,y=342-vals[i]*2.05;s+=`<path d="M${x} 350L${x} ${y}Q${x+21} ${y-6} ${x+42} ${y}L${x+42} 350Z" fill="${i===vals.indexOf(min)?'#9c8061':'#6e8060'}" stroke="#b5b08a" stroke-width="1"/>`;s+=text(x+21,y-15,names[i],17,i===vals.indexOf(min)?C.gold:C.green)}s+=`<path d="M212 350L212 ${342-min*2.05}Q354 ${320-min*2.05} 492 ${342-min*2.05}L492 350Z" fill="#8dc8cd" opacity=".28"/>`;s+=path('M207 303Q353 335 501 303','#d2bd85',5)+path('M207 335Q353 367 501 335','#d2bd85',5);s+=plant(586,270,.62);if(!cover){s+=text(360,50,'相对满足度',13,C.muted);s+=text(360,85,`${min}%`,34,C.gold);s+=text(584,315,`限制养分：${lim}`,14,C.gold);s+=text(360,408,'供给 / 需求的相对比例 · 最小值模型示意',11,C.muted)}return frame(s,'最小养分律木桶模型')}
function nitrogen(p={},step=3,cover=false){const nodes=[{x:150,y:220,t:'有机氮',sub:'残体 · 有机质',c:C.green},{x:340,y:220,t:'NH₄⁺',sub:'铵态氮',c:C.gold},{x:535,y:220,t:'NO₃⁻',sub:'硝态氮',c:C.blue}];let s=plant(552,115,.44);const links=['M205 220L285 220','M395 220L480 220','M535 170Q570 150 553 114'];links.forEach((d,i)=>{s+=path(d,C.muted,1.5,'marker-end="url(#arrow)"');if(step>i)s+=flow(d,[C.gold,C.blue,C.green][i],i)});nodes.forEach((n,i)=>{s+=`<circle cx="${n.x}" cy="${n.y}" r="53" fill="${n.c}" opacity="${step>=i?'.1':'.03'}" stroke="${n.c}" stroke-width="1"/>`;s+=text(n.x,n.y+6,n.t,24,n.c);if(!cover)s+=text(n.x,n.y+80,n.sub,12,C.muted)});if(!cover){s+=text(245,197,'矿化',12,C.gold)+text(438,197,'硝化',12,C.blue);s+=text(439,246,'经 NO₂⁻',10,C.muted);if(step===3){s+=path('M555 270L590 348',C.blue,1,'marker-end="url(#arrow)"')+flow('M555 270L590 348',C.blue);s+=text(601,376,'淋失',13,C.blue);s+=path('M577 192Q662 141 641 74',C.muted,1,'stroke-dasharray="4 5" marker-end="url(#arrow)"')+text(641,58,'反硝化 → N₂ / N₂O',12,C.muted);s+=text(491,111,'吸收 ↑',12,C.green)}s+=text(360,414,'主路径示意 · 硝化通常需氧，反硝化常发生于缺氧条件',10,C.muted)}return frame(s,'土壤氮素转化路径')}
function blocks(p={},step=3,cover=false){let rows=p.rows||[[0,1,2,3],[2,0,3,1],[1,3,0,2]],colors=['#9ebd85','#d6bf81','#92bbc0','#c59881'];let s=`<ellipse cx="364" cy="311" rx="243" ry="60" fill="#091f1a" opacity=".3"/>`;s+=`<g transform="translate(151 123) matrix(1 .22 -.52 .65 60 0)">`;for(let r=0;r<3;r++){if(step>=1)s+=`<rect x="-10" y="${r*103-9}" width="440" height="100" rx="5" fill="none" stroke="#ced7b2" stroke-opacity=".5" stroke-dasharray="5 5"/>`;for(let c=0;c<4;c++){let idx=step<2?c:rows[r][c],x=c*108,y=r*103;s+=`<path d="M${x} ${y}H${x+96}V${y+82}H${x}Z" fill="${colors[idx]}" opacity="${.9-r*.12}"/>`;for(let j=0;j<4;j++){for(let q=0;q<3;q++)s+=`<path d="M${x+18+j*19} ${y+18+q*22}v-8m0 4l-4-3m4 3l4-3" stroke="#2c563e" stroke-width="2" fill="none"/>`}if(!cover)s+=text(x+48,y+72,['CK','N','P','NP'][idx],13,'#244333')}}s+='</g>';if(!cover){s+=text(108,94,'肥力高',12,C.green)+text(91,342,'肥力低',12,C.muted)+path('M105 114L55 292',C.muted,1,'marker-end="url(#arrow)"');if(step>=1)s+=text(553,171,'区组 I',13,C.green)+text(505,243,'区组 II',13,C.green)+text(454,315,'区组 III',13,C.green);s+=text(360,409,step<2?'同一区组内条件相近':'每个区组包含全部处理 · 区组内独立随机',12,C.muted)}return frame(s,'随机完全区组田间试验')}
function normal(p={},step=3,cover=false){let s='';for(let i=0;i<7;i++)s+=path(`M${100+i*85} 105V333`,'#446650',.6);s+=path('M90 333H635','#8eaa8a',1);let d='';for(let x=95;x<=625;x+=3){let y=330-224*Math.exp(-.5*((x-360)/77)**2);d+=`${x===95?'M':'L'}${x} ${y}`};s+=`<path d="${d}L625 333H95Z" fill="url(#water)"/>`+path(d,C.green,3)+path('M360 103V333',C.gold,1,'stroke-dasharray="4 5"');s+=text(360,367,'μ',18,C.gold);return frame(s,'正态分布概率密度曲线')}
function interaction(p={},step=1,cover=false){let v=p.effect??0;let y00=20,y10=40,y01=35,y11=55+v;const X=x=>175+x*380,Y=y=>338-y*2.7;let s=path('M150 70V338H620',C.muted,1);for(let y=20;y<=80;y+=20){s+=path(`M150 ${Y(y)}H620`,'#41614c',.7);if(!cover)s+=text(131,Y(y)+4,y,11,C.muted)};[[y00,y10,C.gold],[y01,y11,C.blue]].forEach(([a,b,c])=>{s+=path(`M${X(0)} ${Y(a)}L${X(1)} ${Y(b)}`,c,3);[a,b].forEach((y,i)=>{s+=`<circle cx="${X(i)}" cy="${Y(y)}" r="6" fill="${c}"/>`;if(!cover)s+=text(X(i)+(i?21:-23),Y(y)+5,y,13,c)})});if(!cover){s+=text(175,369,'低氮 N₀',13,C.muted)+text(555,369,'高氮 N₁',13,C.muted)+text(175,64,'响应值（模拟单位）',12,C.muted,'start');s+=text(367,398,`交互对比 = (${y11} − 35) − (40 − 20) = ${v}`,14,C.green);s+=text(478,88,'● 低磷 P₀',12,C.gold)+text(592,88,'● 高磷 P₁',12,C.blue)}return frame(s,'氮磷两因素交互作用响应图')}
global.PlantScenes={uptake,minimum,nitrogen,blocks,normal,interaction};
})(typeof window==='undefined'?globalThis:window);
